<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Content moderation | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/admin.css"></head><body class="dashboard-page"><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/account">Dashboard</a><a href="/admin/vendors">Vendors</a></nav></header><main class="vendor-management"><p class="eyebrow">Administrator workspace</p><h1>Cultural journal</h1><p>Approve stories, photos and short videos before publication.</p><div class="management-table"><div class="management-row management-header"><span>Story</span><span>Type</span><span>Status</span><span>Action</span></div><?php foreach ($stories as $story): ?><div class="management-row"><span><strong><?= htmlspecialchars($story['title']) ?></strong><small><?= htmlspecialchars($story['author']) ?></small></span><span><?= htmlspecialchars($story['media_type']) ?></span><span><?= htmlspecialchars($story['status']) ?></span><?php if ($story['status'] === 'pending'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="content_id" value="<?= htmlspecialchars((string) $story['id']) ?>"><button class="button" name="status" value="approved">Approve</button><button class="button button-muted" name="status" value="rejected">Reject</button></form><?php endif; ?></div><?php endforeach; ?></div></main></body></html>
